function downloadCSV(rows, name, provenance) {
  if (!rows?.length) return;
  const context=typeof provenance==='object'?provenance:{data_source:provenance};
  const data=rows.map(r=>({...context,...r}));
  const keys=[...new Set(data.flatMap(r=>Object.keys(r)))];
  const cell=v=>{let t=typeof v==='object'?JSON.stringify(v):String(v??'');if(/^[=+@\-\t\r]/.test(t))t="'"+t;return '"'+t.replaceAll('"','""')+'"'};
  const blob=new Blob(['\ufeff'+[keys.map(cell).join(','),...data.map(r=>keys.map(k=>cell(r[k])).join(','))].join('\r\n')],{type:'text/csv;charset=utf-8'});
  const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`vigil-${name}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);
}
async function request(path, options={}) {
  const res=await fetch(path,options);const json=await res.json();if(!res.ok)throw new Error(json.error?.message || json.error || json.message || `Request failed (${res.status})`);return json;
}
