 const [search,setSearch]=useState(''),[page,setPage]=useState(0),[sort,setSort]=useState(null),[desc,setDesc]=useState(true);
 const requestContext=useContext(RequestContext);const sectionName={signals:'signals',severity:'severity',reports:'reports',reactions:'core',bursts:'core'}[name];const retrieval=sectionName&&requestContext?sectionState(requestContext.state,sectionName):null;const provenance={...(typeof source==='object'?source:{data_source:source}),...(retrieval?.result?{retrieved_at:retrieval.result.freshness?.retrieved_at||retrieval.result.generated_at,data_status:retrieval.status}: {})};
 useEffect(()=>setPage(0),[data,search,sort,desc]);
 const cols=columns||Object.keys(data[0]||{}).filter(key=>key!=='reaction_terms').slice(0,7).map(k=>({key:k,label:columnLabel(k)}));
 let rows=data.filter(r=>!search||Object.values(r).join(' ').toLowerCase().includes(search.toLowerCase()));
 if(sort)rows=[...rows].sort((a,b)=>typeof a[sort]==='number'?(a[sort]-b[sort])*(desc?-1:1):String(a[sort]??'').localeCompare(String(b[sort]??''))*(desc?-1:1));
 const count=rows.length,pages=Math.max(1,Math.ceil(count/10)),safePage=Math.min(page,pages-1);
