 <div className="source-line"><span className="source-indicator"><span className={`status-dot ${reference?'lavender':''}`}/>{sourceLabel}</span><span className="source-description">{reference?'Illustrative data · no clinical conclusions':'Spontaneous reports · association ≠ causation'}</span>{pendingChanges&&<span className="pending-note" role="status">Unapplied changes</span>}<button className="icon-btn" title="Reload current cohort (cached for up to five minutes)" aria-label="Refresh current cohort" onClick={()=>setRefresh(value=>value+1)} disabled={dashboardBusy}><RefreshCw size={13}/></button></div>
