 {view==='overview'&&<>{data&&<div className="stats-grid">{stats.map((s,i)=><div className={`stat-card glass stat-${i}`} key={s.label}><div className="stat-top"><span>{s.label}</span><s.icon size={16}/></div><div className="stat-number">{s.value}{i<2&&<svg viewBox="0 0 90 35" aria-hidden="true"><polyline points={entries(data.timeseries).slice(-12).map((r,j,a)=>`${j*8},${32-(Number(r.count)||0)/Math.max(1,...a.map(x=>Number(x.count)||0))*28}`).join(' ')} fill="none" stroke="currentColor" strokeWidth="1.6"/></svg>}</div><p>{s.detail}</p></div>)}</div>}<div className="overview-grid"><Panel section="core" title={`Weekly ${unit}`} description={`${titleCase(params.drug)} · ${fmt(summary.weeks)} weeks in view`} action={<Tag><span className="status-dot"/> Volume over time</Tag>} className="trend-panel"><TimeSeriesChart recordLabel={unit} data={entries(data.timeseries)} drug={titleCase(params.drug)} compareDrug={titleCase(params.compare)} compareData={comparisonSeries?entries(data.timeseries).map(r=>({date:r.date,count:r.compare_count})):undefined}/><div className="chart-foot"><span><span className="legend-dot"/> {titleCase(params.drug)}</span><span>Week received · {reference?'synthetic reviews':'FAERS reports'}</span></div></Panel><Panel section="signals" title="Evidence brief" eyebrow="ASSISTED EXPLORATION" action={<Sparkles size={17} className="mint"/>} className="brief-panel"><div className="brief-source"><span className="status-dot"/> Computed from this cohort</div><div className="brief-item"><span className="brief-number">01</span><div><h3>{leadingReaction?`${titleCase(leadingReaction.reaction)} leads the mentions`:'Start with reaction coverage'}</h3><p>{leadingReaction?`${fmt(leadingReaction.count)} ${unit} mention this reaction. Counts describe the selected cohort, not incidence.`:'No reaction counts are available for this cohort.'}</p></div></div><div className="brief-item"><span className="brief-number">02</span><div><h3>{fmt(summary.signal_count??(signalsReady?signals.filter(s=>s.signal).length:null))} patterns meet the flag rule</h3><p>Review PRR, confidence intervals, and supporting counts before interpreting a signal.</p></div></div><button className="btn brief-action" onClick={()=>navigate('signals')}>Inspect signals <ArrowUpRight size={15}/></button><div className="brief-disclaimer"><Info size={13}/> Rule-based summary · no generated medical advice</div></Panel><Panel section="core" title="Most mentioned reactions" description={`Top ${Math.min(6,reactions.length)} · counts in selected cohort`} action={<button className="icon-btn" aria-label="View all reactions" onClick={()=>navigate('reactions')}><ArrowUpRight size={18}/></button>}><HorizontalBars onSelect={selectReaction} selectedReaction={reaction} data={reactions.slice(0,6)} showComparison={comparisonReactions} compareLabel={titleCase(params.compare)} valueLabel={reference?'Reviews':'Reports'}/></Panel><Panel section="core" dependencies={params.compare?['signals','comparison']:['signals']} title="Connected evidence" description="Drug–reaction relationships at a glance" action={<button className="icon-btn" aria-label="Explore network" onClick={()=>navigate('network')}><ArrowUpRight size={18}/></button>} className="network-mini"><NetworkGraph compact selectedReaction={reaction} onReactionChange={selectReaction} data={data.graph||signals} recordLabel={unit} drug={titleCase(params.drug)}/></Panel></div></>}
